"""Local static gallery for #308, using actual native images only."""
import argparse
import html
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
p=argparse.ArgumentParser();p.add_argument('--workspace',type=Path,required=True);args=p.parse_args()
out=args.workspace/'build/local-cavern-rest-v1';report=json.loads((out/'native/validation.json').read_text())
catalog=json.loads((ROOT/'art/props/cavern-rest-v1/catalog.json').read_text())
assert not report['failures'],report['failures']
for name in report['captures']:assert (out/'native'/name).is_file(),name
hero=''.join(f'<article><h2>{title}</h2><a class="shot" href="native/{name}-eye-height.png"><img src="native/{name}-eye-height.png" data-neutral="native/{name}-eye-height.png" data-phone="native/{name}-eye-height-phone.png" alt="{title}"></a><p>{note}</p></article>' for name,title,note in [
 ('cavern-rift-identity','Cavern · tall narrow rift','First-person art composition. Foreground ledge is level; far tiers are scenery. No player controller or playable elevation prototype.'),
 ('rest-area-approach','Rest Area · sheltered approach','Full 4×4-cell composition with grounded tent/bedroll, paper map, supplies, bankable fire and lookout edge. Requires deliberate room/roof reservation.')])
cards=[]
for row in catalog['scenes']:
    for state in row['states']:
        name=row['id']+'-'+state;cost=report['scene_costs'][name]
        cards.append(f'<article><h3>{row["id"]} · {state}</h3><a class="shot" href="native/{name}-neutral.png"><img loading="lazy" src="native/{name}-neutral.png" data-neutral="native/{name}-neutral.png" data-phone="native/{name}-844.png" data-wide="native/{name}-1278.png" alt="{name}"></a><p>{cost["triangles"]:,} triangles · {cost["draws"]} draws · {row["footprint_metres"]}m nominal footprint</p><p>{html.escape(row["note"])}</p></article>')
raw=''.join(f'<article><h3>{r["id"]}</h3><a href="native/raw-{r["id"]}.png"><img loading="lazy" src="native/raw-{r["id"]}.png" alt="{r["id"]}"></a><p>{r["triangles"]:,} triangles · <a href="masters/{r["id"]}.blend">Editable master</a></p></article>' for r in catalog['assets'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Depths · Cavern and Rest Area</title><style>body{margin:0;background:#10181c;color:#ddd4bd;font:16px/1.55 system-ui}main{max-width:1500px;margin:auto;padding:30px}h1,h2,h3{font-family:Georgia,serif;color:#d2b480}h1{font-size:38px}a{color:#d2b480}header{border-bottom:1px solid #746246;padding-bottom:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:20px}article{background:#182125;border:1px solid #58605b}article h2,article h3,article p{margin:16px}img{width:100%;display:block}.tools{position:sticky;top:0;padding:10px;background:#10181cf5;z-index:2}button{font:inherit;padding:10px 16px;color:#eadfc7;background:#27302d;border:1px solid #8b744e;margin:4px;cursor:pointer}small{color:#aeb9b4}</style><main><header><small>DEPTHS · #308 · ACTUAL NATIVE MOBILE CAPTURES</small><h1>Cavern identity &amp; Rest Area approach</h1><p>22 original solid exports, 30 registered scenes, three new original albedos (512px mipmapped runtime imports), four surface materials and a candidate theme. Existing verified bones, structures, hearth and lantern are reused. Editable masters stay local.</p><p>CHECKS checks passed · SHOTS captures · desktop/1278×590/844×390 · private desktop/profile, no owner saves or foreground changes.</p><p><a href="native/validation.json">Measured budgets &amp; check report</a> · <a href="native-launch/launch.json">Isolation record</a></p></header><h2>First-person compositions</h2><div class="tools" data-target="hero"><button data-mode="neutral">1278×590</button><button data-mode="phone">844×390</button></div><div class="grid" id="hero">HERO</div><h2>Registered scenes and all states</h2><div class="tools" data-target="scenes"><button data-mode="neutral">Neutral</button><button data-mode="wide">1278×590 / torch</button><button data-mode="phone">844×390 / torch</button></div><div class="grid" id="scenes">CARDS</div><h2>Original detail exports</h2><div class="grid">RAW</div><h2>Actual existing event adapter</h2><a href="native/live-refuge-restored.png"><img src="native/live-refuge-restored.png" alt="Main restored refuge marker"></a><p>The compact one-cell 3D refuge marker is bound in refuge_scouts.prop. The real Main prop factory and saved empty-state adapter select its banked appearance without starting the Main save/game loop. Existing rest, loot, route, service and Overlook rules stay unchanged.</p><h2>Integration boundaries</h2><p>The full approach needs a reserved 4×4 room plus wall thickness and 5.3m roof clearance. The tall rift requires reserved void/roof geometry; far ledges are not reachable routes. No walkable slopes, new map layers or playable elevation prototype. Existing owner-approved Overlook screen and actual present-party mapping remain authoritative. Physical iPhone performance and complete live/exported floor integration remain.</p><p>Damp Caves hookup is prepared separately for Claude in docs/damp-caves-hookup-for-claude.md (PR #303 art kit). Concurrent core exploration/city changes were untouched.</p></main><script>document.querySelectorAll('.tools').forEach(t=>t.querySelectorAll('button').forEach(b=>b.onclick=()=>document.querySelectorAll('#'+t.dataset.target+' .shot img').forEach(i=>{i.src=i.dataset[b.dataset.mode];i.parentElement.href=i.src})));</script></html>'''
page=page.replace('CHECKS',str(report['checks'])).replace('SHOTS',str(len(report['captures']))).replace('HERO',hero).replace('CARDS',''.join(cards)).replace('RAW',raw)
(out/'inspector.html').write_text(page,encoding='utf-8');print(out/'inspector.html')
